FieldID: 130, Name: common.MetaFieldName, IsPrimaryKey: false, Description: "dynamic field", DataType: schemapb.DataType_JSON

// client/column/json.go
type ColumnJSONBytes struct {
	*genericColumnBase[[]byte]
	isDynamic bool
}

// Dynamic fields store arbitrary JSON without type constraints
func NewColumnJSONBytes(name string, values [][]byte) *ColumnJSONBytes {
	return &ColumnJSONBytes{
		genericColumnBase: &genericColumnBase[[]byte]{
			name:      name,
			fieldType: entity.FieldTypeJSON,
			values:    values,
		},
	}
}
